#include "fake_tokens.h"

#include <stdbool.h>  // bool
#include <stdlib.h>   // malloc
#include <string.h>   // strcpy, strlen

// Changes: the interpolated string delimiters carry no text, as from the lexer.
/**
 * @brief Returns whether a token of given type carries heap text
 */
static bool fake_has_text(TokenType type) {
  switch (type) {
    case IDENT:
    case STRING:
    case TRIPLE_STRING:
      return true;
    default:
      return false;
  }
}

// Changes: new, parses a row in a fresh context and returns its exit code.
ExitCode fake_parse_exit(FakeRow row) {
  FakeSource source = {.tokens = row.tokens, .count = row.count};
  Ctx local;
  Flags flags = DEFAULT_TEST_FLAGS;
  flags.verbose = false;
  ctx_init(&local, flags);
  if (setjmp(local.error_target) == 0)
    parser_run(&local, fake_next, &source);
  return ctx_free(&local);
}

// Changes: tokens without a line get the current line; FAKE_LINE_BREAK is an
// EOL_TOKEN that starts a new line; heap text is marked TEXT.
Token fake_next(Ctx* ctx, void* state) {
  (void)ctx;
  FakeSource* source = state;
  if (source->position >= source->count)
    return (Token){.type = EOF_TOKEN, .line = source->breaks + 1};

  Token token = source->tokens[source->position++];
  if (token.type == FAKE_LINE_BREAK)
    token.type = EOL_TOKEN;
  if (token.line == 0)
    token.line = source->breaks + 1;
  if (token.type == EOL_TOKEN)
    source->breaks++;
  if (token.type == FAKE_LEXICAL_ERROR)
    THROW(E_LEXER_ERROR, "fake lexical error");
  if (fake_has_text(token.type)) {
    char* copy = malloc(strlen(token.value.text) + 1);
    strcpy(copy, token.value.text);
    token.value.text = copy;
    token.value_type = TEXT;
  }
  return token;
}
